try { $d = Invoke-RestMethod -Uri "http://127.0.0.1:1933/observer/system" -TimeoutSec 5; $d | ConvertTo-Json -Depth 5 } catch { "observer err: $($_.Exception.Message)" }

# Find any running openviking process & how many sessions/memories dirs exist
Get-Process | Where-Object { $_.ProcessName -match 'openviking|node' } | Select-Object Id,ProcessName,StartTime | Format-Table -Auto | Out-String
$data="$env:USERPROFILE\.openviking"; if(Test-Path $data){ Get-ChildItem $data -Recurse -Directory -ErrorAction SilentlyContinue | Where-Object {$_.Name -match 'memories|sessions|vectordb'} | Select-Object -First 10 FullName }
